out=[r.copy() for r in grid]
# row gaps between consecutive 7s
for i,row in enumerate(grid):
    pos=[j for j,v in enumerate(row) if v==7]
    for a,b in zip(pos,pos[1:]):
        for j in range(a+1,b): out[i][j]=3
# column gaps between consecutive 7s
for j in range(27):
    pos=[i for i in range(23) if grid[i][j]==7]
    for a,b in zip(pos,pos[1:]):
        for i in range(a+1,b): out[i][j]=3
print('\n'.join(' '.join(map(str,r)) for r in out))
